// Writes the entry image for the-passport-page-of-a-countr-2-20261121-0318.
// An invented passport spread for the Republic of Veskar, a small North
// Atlantic island republic (fishing, lighthouses, seabird sanctuaries).
// Left page: data page for EINAR KETILSSON, issued 14 JAN 2026 in Havnvik,
// expires 14 JAN 2036, with a machine-readable strip. Right page: six
// stamps (Havnvik-Bergen-Reykjavik-Havnvik, 21 JAN-09 FEB 2026, all after
// issue), a LIGHTHOUSE DUES fee stamp, and a Skarholm sanctuary condition.
// Deterministic: the same bytes on every run, no network, no randomness.
// Revised once: the portrait hair was redrawn as a full dark cap with grey
// streaks (the first render read as bald); the MRZ was verified 44/44 chars
// with check digits computed by script (doc 0, DOB 6, expiry 3, composite 2).

import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";

const PNG_BASE64 =
  "";
;

const outDir = process.env.MAKEFUN_OUTPUT_DIR || "/output/entry.png";
const dest = outDir.endsWith(".png") ? outDir : join(outDir, "entry.png");

mkdirSync(dirname(dest), { recursive: true });
writeFileSync(dest, Buffer.from(PNG_BASE64, "base64"));
console.log(`wrote ${dest}`);
